public class MeetingPlannerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.time.LocalTime t(int h, int m) {
        return java.time.LocalTime.of(h, m);
    }

    public static void main(String[] args) {
        check("partial overlap", true,
                MeetingPlanner.overlaps(t(9, 0), t(10, 0), t(9, 30), t(10, 30)));
        check("touching endpoints do not overlap", false,
                MeetingPlanner.overlaps(t(9, 0), t(10, 0), t(10, 0), t(11, 0)));
        check("one meeting inside the other", true,
                MeetingPlanner.overlaps(t(9, 0), t(12, 0), t(10, 0), t(11, 0)));
        check("disjoint meetings", false,
                MeetingPlanner.overlaps(t(9, 0), t(10, 0), t(11, 0), t(12, 0)));
        check("identical meetings", true,
                MeetingPlanner.overlaps(t(9, 0), t(10, 0), t(9, 0), t(10, 0)));
        check("minutesBetween 9:15 to 10:45", 90L, MeetingPlanner.minutesBetween(t(9, 15), t(10, 45)));
        check("minutesBetween 8:30 to 17:00", 510L, MeetingPlanner.minutesBetween(t(8, 30), t(17, 0)));
        check("minutesBetween zero-length", 0L, MeetingPlanner.minutesBetween(t(14, 0), t(14, 0)));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

