public class MeetingPlanner {

    public static boolean overlaps(java.time.LocalTime aStart, java.time.LocalTime aEnd,
                                   java.time.LocalTime bStart, java.time.LocalTime bEnd) {
        return aStart.isBefore(bEnd) && bStart.isBefore(aEnd);
    }

    public static long minutesBetween(java.time.LocalTime start, java.time.LocalTime end) {
        return java.time.Duration.between(start, end).toMinutes();
    }
}
